sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

	const request_body = request.body.data;
    gs.info('isc_webhook/incident_management - Request Received - Request Body\r\n\r\n' + JSON.stringify(request_body));

	const gr_incident = new GlideRecord('incident');
	gr_incident.initialize();
	gr_incident.assignment_group = get_assignment_group_id();
	gr_incident.contact_type = 'monitoring';
	gr_incident.description = JSON.stringify(request_body,null,2);


	switch(request_body._metadata.triggerId){
		case 'idn:account-aggregation-completed':
			gr_incident.short_description = 'SailPoint Account Aggregation Failure - ' + request_body.source.name;
		break;
		case 'idn:post-provisioning':
			gr_incident.short_description = 'SailPoint Provisioning Issue - ' + request_body.recipient.name;
		break;
	}

	const res_inc = gr_incident.insert();

	function get_assignment_group_id(){
		const gr_group = new GlideRecord('sys_user_group');
		gr_group.get('name',gs.getProperty('x_xal_idconnect.incident_assignment_group'));

		return gr_group.sys_id.toString();
	}

})(request, response);
